  insert into public.brands (name, website, description, country, status) values ('BURST Oral Care', 'https://www.burstoralcare.com', 'Subscription oral-care brand (sonic toothbrushes, toothpaste, whitening strips) selling heavily through TikTok Shop affiliates — an estimated 94% of its TikTok Shop sales in the 30 days to Nov 6, 2026 came through affiliate creators. Its separate ambassador program is restricted to dental professionals, so the creator route is TikTok Shop; published commission percentages conflict across listings, so the rate is recorded as null.', 'United States', 'published') returning id into bid;
