  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BURST Oral Care TikTok Shop Affiliate Program', 'https://rateful.ai/brand/burst-oral-care', 'https://rateful.ai/brand/burst-oral-care', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rateful.ai/brand/burst-oral-care', 'listing', 'affiliate', 'Rateful''s BURST Oral Care page, built from TikTok Shop data, states that about 94% of the brand''s estimated $155K in TikTok Shop sales in the 30 days to Nov 6, 2026 came through affiliate creators'' videos and LIVEs, and that creators with TikTok Shop affiliate access can add its products to their showcase and earn commission on every sale.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/burstoralcare-com-affiliate-program', 'listing', 'affiliate', 'Published percentages for BURST conflict across fetched listings — Shopper lists 5% per sale, Lasso lists up to 15%, and a dental-marketing roundup cites up to 20% — so commission_rate is set to null rather than picking one.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://about.burstoralcare.com/ambassador', 'official_site', 'general', 'The brand''s own ambassador page is aimed at dentists, dental hygienists and dental assistants only, so that route is a trade/professional program and is not the basis for this entry; the consumer creator route is TikTok Shop.', 'verified', now());
