  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 15, 7, 6, 8, 4, '{"niche_fit": "Oral care sits at the edge of beauty; the products demo well in short-form video but the niche is narrower than skincare or makeup.", "ugc_evidence": "An estimated 94% of its TikTok Shop sales come through affiliate creators \u2014 direct evidence of a working creator channel.", "compensation": "Commission is paid on TikTok Shop sales, but published percentages conflict (5% vs up to 15% vs up to 20%), so the rate is unverified and recorded as null.", "contact_access": "No public creator contact is published; joining happens inside TikTok Shop.", "opportunity_availability": "Any creator with TikTok Shop affiliate access can add the products to their showcase.", "credibility": "A well-known subscription oral-care brand with substantial TikTok Shop volume."}'::jsonb);
