  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 10, 13, 8, 4, '{"compensation": "A real commission exists (up to 10% on Awin/LTK per the brand''s own page) but only as a ceiling with no flat published rate, so it scores mid-range.", "contact_access": "A public programme page on the official site plus a published marketing email for affiliate questions \u2014 top band per the rubric.", "credibility": "Established direct-to-consumer womenswear label with its own store and programmes on two major creator networks.", "niche_fit": "Distinctive boho/rock womenswear is highly visual and try-on friendly \u2014 a strong fashion UGC niche.", "opportunity_availability": "Open application through Awin; the LTK route additionally requires a 5k+ engaged audience per the brand''s own page.", "ugc_evidence": "The brand recruits creators directly (''We''re on the lookout for creatives''), runs gifting and early-access perks, and is built around influencer styling content."}'::jsonb);
