  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://buffery.us/pages/affiliate-program-agreement', 'official_site', 'affiliate', 'Buffery''s own Affiliate Program Agreement publishes a three-tier commission structure earned through a unique discount code: Tier 1 ''Knows a Guy'' 10% for all approved affiliates, Tier 2 ''Good for It'' 12% at $2,500+ net completed sales in a rolling 90-day period, Tier 3 ''The Go-To'' 15% at $7,500+.', 'verified', now());
