  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliatemonkey.com/affiliate/thredup-inc-affiliate-program/', 'listing', 'general', 'ThredUp is described as one of the largest online consignment and thrift stores for secondhand clothes, offering a sustainable alternative to traditional retail through reuse of textiles.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliatemonkey.com/affiliate/thredup-inc-affiliate-program/', 'listing', 'commission_cap', 'No fetched source states any cap on ThredUp affiliate earnings, so commission_cap is recorded as unknown; no source publishes absolute creator counts, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 6, 6, 7, 5, '{"compensation": "A CJ program exists, but published rates conflict widely (up to 5% vs 10-15% vs 10-30%), so no rate could be verified \u2014 low score until confirmed in the network.", "contact_access": "No public partnerships email or on-site application page could be verified from fetched pages; joining is through CJ Affiliate only.", "credibility": "One of the largest resale platforms in the world and a publicly traded company \u2014 top-tier brand credibility.", "niche_fit": "Thrift hauls and secondhand styling are a huge, proven fashion-creator niche on TikTok and YouTube.", "opportunity_availability": "Application through CJ Affiliate with approval by ThredUp''s affiliate management team per directory listings.", "ugc_evidence": "The program explicitly targets bloggers and influencers, and thrifting content is creator-driven, but no dedicated creator program page exists on the brand''s own site."}'::jsonb);
