  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Workaway Affiliate Program', 'https://www.workaway.info/en/community/affiliates', 'https://www.workaway.info/en/community/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.workaway.info/en/community/affiliates', 'official_site', 'affiliate', 'Workaway''s own Affiliate Program page states affiliates earn commission with every successful sign up through their personal invite link and receive monthly commission via PayPal, with opportunities for bonus collaborations; travel content creators who run a blog, website or social platform with an engaged audience are invited to apply from the page, and non-members can apply too.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.workaway.info/en/community/affiliates', 'official_site', 'general', 'The page describes Workaway as a work-exchange community built since 2002, spanning 170+ countries with 50,000+ opportunities and 736,059 reviews, positioned as ''the Airbnb of working holidays''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.workaway.info/en/community/affiliates', 'official_site', 'compensation', 'Workaway publishes no commission rate or flat amount on its affiliate page, so commission_rate is null. The separate invite-a-friend ladder for existing members pays free membership months and gift codes; that ladder is distinct from the Affiliate Program''s cash commission paid monthly via PayPal.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.workaway.info/en/community/affiliates', 'official_site', 'commission_cap', 'No fetched source states any cap on Workaway affiliate earnings, so commission_cap is recorded as unknown; no source publishes absolute creator counts, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 6, 9, 8, 5, '{"compensation": "Cash commission paid monthly via PayPal is confirmed on the brand''s own page, but no rate or amount is published, so compensation scores low until terms are shared at application.", "contact_access": "A public affiliate page on the official site with a direct creator application route, though no published partnerships email.", "credibility": "Operating since 2002 with 170+ countries, 50,000+ opportunities and over 736,000 reviews \u2014 a long-established travel community.", "niche_fit": "Work-exchange and slow-travel experiences are a distinctive, story-rich niche for travel creators.", "opportunity_availability": "Open application for travel content creators from the official page; members can also start sharing immediately via their invite link.", "ugc_evidence": "The program is explicitly built for travel content creators and bloggers, with bonus collaborations offered beyond the base commission."}'::jsonb);
