  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Roambee Partner Programme', 'https://roambee.io/partners', 'https://roambee.io/partners', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://roambee.io/partners', 'official_site', 'affiliate', 'Roambee''s own partner programme page publishes tiered commission: every partner starts at Tier 1 10%, rising to 15% from €1,000 and 20% from €4,250 in prior-quarter net sales; commission is a percentage of the net amount paid (after discounts and perks, excluding VAT and payment fees), earned on what each customer buys for 12 months, with payouts from €50 by bank transfer, PayPal or USDT and a 30-day last-click window.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://roambee.io/partners', 'official_site', 'contact', 'The partner page publishes partners@roambee.io for questions about codes, payouts or collaborations, and applications are made by signing in at partners.roambee.io.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://roambee.io/', 'official_site', 'commission_cap', 'The ''No cap'' wording on Roambee''s homepage applies to free data gifted through its traveller-to-traveller referral scheme, not to partner earnings, so it does not qualify as an uncapped statement; commission_cap is unknown and no creator counts are published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 14, 13, 8, 3, '{"compensation": "Published tiers on the brand''s own page \u2014 10% starting, up to 20% \u2014 calculated on net spend with a 12-month earning window per customer; strong for the eSIM niche.", "contact_access": "A public partner page with an application route plus a published partners@ inbox answered by a person \u2014 top band per the rubric.", "credibility": "A newer, smaller eSIM brand; the program terms are unusually transparent, but the company has a short track record.", "niche_fit": "Travel eSIMs are one of the most promoted products in travel content right now \u2014 strong fit for travel creators.", "opportunity_availability": "Open, free application for creators, bloggers, agencies and hospitality businesses via the partner portal.", "ugc_evidence": "The programme is marketed directly to travel creators, bloggers and podcasters with worked commission examples by creator type."}'::jsonb);
