  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/allianz-global-assistance/', 'affiliate_network', 'affiliate', 'Lasso''s directory lists the Allianz Global Assistance program on CJ Affiliate at a flat $12-$25 per sale with a 45-day cookie and a $50 payout threshold, with application through CJ and manual review.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateprogramsguru.com/programs/allianz-travel-affiliate-program/', 'listing', 'compensation', 'Affiliate Programs Guru reports the program runs on CJ Affiliate (primarily US), Awin (UK/EU), FlexOffers and Travelpayouts, paying $12-$25 per confirmed sale on CJ and a percentage model of up to 12% of policy value on some networks. Because the model differs by network (flat bounty vs percentage), commission_rate is recorded as null with both structures documented here.', 'publicly_reported', now());
