  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 9, 10, 8, 7, 5, '{"compensation": "Documented flat bounties of $12-$25 per confirmed sale on CJ (and up to 12% of policy value on some networks) \u2014 real published pay, though the rate could not be reduced to one figure.", "contact_access": "A dedicated affiliate portal on the brand''s own site with sign-up, FAQ and content hub, though joining itself happens inside CJ.", "credibility": "Allianz is one of the world''s largest insurance and assistance groups \u2014 maximum brand credibility.", "niche_fit": "Travel insurance is a staple recommendation in travel content, though less visual than product niches.", "opportunity_availability": "Application through CJ Affiliate with manual review of the publisher''s site per directory listings.", "ugc_evidence": "The publisher network provides a content hub to help affiliates educate audiences, but it is a publisher program rather than a creator-first program."}'::jsonb);
