  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://medjetassist.com/affiliates-and-influencers', 'official_site', 'affiliate', 'Medjet''s own affiliates and influencers page states its affiliate partner is Awin, that signing up is cost free, and that affiliates, influencers and content entrepreneurs can join the ''hundreds of affiliates and resellers'' earning commissions selling Medjet memberships, with sub-affiliate routes including Viglink, Skimlinks, FlexOffers and Mavely.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/20001?setLocale=pl_PL', 'affiliate_network', 'affiliate', 'Medjet''s Awin merchant profile states a standard 5% commission rate with a cap of $75 per transaction, a 45-day cookie period and a dedicated affiliate management team.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/20001?setLocale=pl_PL', 'affiliate_network', 'commission_cap', 'The $75 figure in the Awin listing is a per-transaction commission cap, not a cap on total earnings, so commission_cap is recorded as unknown. The brand''s own ''hundreds of affiliates'' wording is a few-hundred-scale figure, which does not meet the absolute small-count bar for low, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 11, 9, 8, 8, 4, '{"compensation": "A published 5% standard rate on Awin (capped at $75 per transaction) on high-priced memberships starting at $99-$315 \u2014 modest percentage, meaningful basket size.", "contact_access": "A dedicated affiliates and influencers page on the brand''s own site explains the routes in, though application itself happens inside Awin.", "credibility": "Long-running, top-rated medical transport membership brand with a dedicated affiliate management team.", "niche_fit": "Travel safety and medical evacuation is a credible but narrower travel niche \u2014 strongest for adventure, expat and senior-travel creators.", "opportunity_availability": "Cost-free sign-up through Awin, plus sub-affiliate routes (Mavely, Skimlinks, Viglink) that lower the barrier for influencers.", "ugc_evidence": "The brand maintains a dedicated page courting affiliates and influencers and supports creator-friendly sub-networks such as Mavely."}'::jsonb);
