  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 12, 6, 8, 3, '{"compensation": "A published 15% commission on the Offerspilot route is a strong rate for travel eSIM; a separate up-to-20% claim could not be verified and is flagged in the evidence.", "contact_access": "No public partnerships email or brand-owned application page could be verified; joining is through Offerspilot or Involve Asia publisher accounts.", "credibility": "A smaller, newer eSIM brand; program details come from network-side sources rather than a brand-owned page.", "niche_fit": "Pay-as-you-go eSIM is a distinctive, easy-to-explain product for travel creators \u2014 strong niche fit.", "opportunity_availability": "Publisher sign-up on Offerspilot with a campaign application, and an Involve Asia route that may be instant-apply.", "ugc_evidence": "Both network listings aim the program squarely at travel creators and bloggers, though the brand publishes no creator program page of its own that could be verified."}'::jsonb);
