  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://krisp.ai/partners/', 'official_site', 'compensation', 'The page''s FAQ asks ''Does Krisp have an affiliate program, and how much can I earn?'' and answers that the program pays 30% recurring for 12 months and ''there''s no cap on what you can earn'' — an explicit no-cap statement from the brand, so the cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://krisp.ai/partners/', 'official_site', 'ugc_collab', 'The page explicitly invites influencers and creators (including beginners), offers an asset and swipe-copy library, monthly creative drops and partner office hours, and says audience size matters less than how and where the partner will promote.', 'verified', now());
